//
// An entry the tree already has keeps its legacy layer index and name (LAYR, LANR).
// VPX replaced layers with part groups and only re-derives those two when it saves,
// renumbering the index and inventing a name wherever the table never recorded one,
// so writing them would rewrite every entry of the index for a save that changed
// nothing. A part that is new to the tree has no recorded value to keep, so its
// entry takes VPX's.
static constexpr SrcField c_srcIndexFields[] = {
   { 'L' | ('O' << 8) | ('C' << 16) | ('K' << 24), "is_locked", nullptr, SrcValueKind::Bool, -1, nullptr, 0 },
   { 'L' | ('V' << 8) | ('I' << 16) | ('S' << 24), "editor_layer_visibility", nullptr, SrcValueKind::Bool, -1, nullptr, 0 },
};

static constexpr SrcField c_srcIndexFieldsNew[] = {
   { 'L' | ('O' << 8) | ('C' << 16) | ('K' << 24), "is_locked", nullptr, SrcValueKind::Bool, -1, nullptr, 0 },
   { 'L' | ('V' << 8) | ('I' << 16) | ('S' << 24), "editor_layer_visibility", nullptr, SrcValueKind::Bool, -1, nullptr, 0 },
   { 'L' | ('A' << 8) | ('Y' << 16) | ('R' << 24), "editor_layer", nullptr, SrcValueKind::Int, -1, nullptr, 0 },
   { 'L' | ('A' << 8) | ('N' << 16) | ('R' << 24), "editor_layer_name", nullptr, SrcValueKind::String, -1, nullptr, 0 },
};

static constexpr SrcTypeFields c_srcIndexType = { "gameitems.json", c_srcIndexFields, 2 };
static constexpr SrcTypeFields c_srcIndexTypeNew = { "gameitems.json", c_srcIndexFieldsNew, 4 };

